import urllib.request, urllib.error, json

base = "http://172.28.0.3:8081"
candidates = []
verbs = ["price","prices","pricing","quote","quotes","sku","skus","product","products","rate","rates","cost","costs"]
prefixes = ["", "api", "v1", "v2", "api/v1", "api/v2", "svc", "internal"]
for pre in prefixes:
    for v in verbs:
        path = f"/{pre}/{v}/A100" if pre else f"/{v}/A100"
        candidates.append(path)
        path2 = f"/{pre}/{v}" if pre else f"/{v}"
        candidates.append(path2)
candidates += ["/price?sku=A100", "/api/v1/price?sku=A100", "/query?sku=A100", "/A100", "/get_price/A100", "/get/A100"]

interesting = []
for path in candidates:
    req = urllib.request.Request(base + path)
    try:
        r = urllib.request.urlopen(req, timeout=3)
        interesting.append((path, r.status, r.read()[:200]))
    except urllib.error.HTTPError as e:
        if e.code != 404:
            interesting.append((path, e.code, e.read()[:200]))
    except Exception as e:
        pass
for path, code, body in interesting:
    print(code, path, body)
print("done")
EOF"}

